BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
-- No object OIDs, row values, role passwords, foreign options or connection
-- strings leave the catalog. Privileges are canonical semantic tuples.
WITH namespaces AS MATERIALIZED (
 SELECT * FROM pg_namespace WHERE nspname !~ '^pg_' AND nspname <> 'information_schema'
), relations AS MATERIALIZED (
 SELECT c.*,n.nspname FROM pg_class c JOIN namespaces n ON n.oid=c.relnamespace
 WHERE c.relkind IN ('r','p','v','m','S','f') AND NOT EXISTS
 (SELECT 1 FROM pg_depend e WHERE e.classid='pg_class'::regclass AND e.objid=c.oid AND e.deptype='e')
), routines AS MATERIALIZED (
 SELECT p.*,n.nspname FROM pg_proc p JOIN namespaces n ON n.oid=p.pronamespace
 WHERE NOT EXISTS (SELECT 1 FROM pg_depend e WHERE e.classid='pg_proc'::regclass AND e.objid=p.oid AND e.deptype='e')
), types AS MATERIALIZED (
 SELECT t.*,n.nspname FROM pg_type t JOIN namespaces n ON n.oid=t.typnamespace
 LEFT JOIN pg_class c ON c.oid=t.typrelid
 WHERE t.typtype IN ('b','c','d','e','r','m') AND (t.typtype<>'b' OR t.typelem=0)
 AND (t.typtype<>'c' OR c.relkind='c') AND NOT EXISTS
 (SELECT 1 FROM pg_depend e WHERE e.classid='pg_type'::regclass AND e.objid=t.oid AND e.deptype='e')
)
SELECT jsonb_build_object(
 'extensions',(SELECT jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'owner',pg_get_userbyid(e.extowner),'owner_dependencies',coalesce((SELECT jsonb_agg(pg_get_userbyid(d.refobjid) ORDER BY pg_get_userbyid(d.refobjid)) FROM pg_shdepend d WHERE d.dbid=(SELECT oid FROM pg_database WHERE datname=current_database()) AND d.classid='pg_extension'::regclass AND d.objid=e.oid AND d.objsubid=0 AND d.refclassid='pg_authid'::regclass AND d.deptype='o'),'[]'::jsonb)) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'schemas',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(ax.grantor),'grantee',CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,'privilege',ax.privilege_type,'grantable',ax.is_grantable) ORDER BY pg_get_userbyid(ax.grantor),CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,ax.privilege_type,ax.is_grantable) FROM aclexplode(CASE WHEN cardinality(coalesce(n.nspacl,acldefault('n',n.nspowner)))>0 THEN coalesce(n.nspacl,acldefault('n',n.nspowner)) END) ax),'[]'::jsonb)) ORDER BY n.nspname) FROM namespaces n),
 'relations',(SELECT jsonb_agg(jsonb_build_object(
 'schema',c.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(ax.grantor),'grantee',CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,'privilege',ax.privilege_type,'grantable',ax.is_grantable) ORDER BY pg_get_userbyid(ax.grantor),CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,ax.privilege_type,ax.is_grantable) FROM aclexplode(CASE WHEN cardinality(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner)))>0 THEN coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner)) END) ax),'[]'::jsonb),
 'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',ARRAY(SELECT x FROM unnest(c.reloptions) x ORDER BY x),
 'persistence',c.relpersistence,'replica_identity',c.relreplident,'access_method',(SELECT amname FROM pg_am WHERE oid=c.relam),
 'tablespace',CASE WHEN c.reltablespace=0 THEN NULL ELSE (SELECT spcname FROM pg_tablespace WHERE oid=c.reltablespace) END,
 'partitioned',c.relispartition,'partition_bound',pg_get_expr(c.relpartbound,c.oid),'partition_key',pg_get_partkeydef(c.oid),
 'parents',ARRAY(SELECT format('%I.%I',pn.nspname,pc.relname) FROM pg_inherits i JOIN pg_class pc ON pc.oid=i.inhparent JOIN pg_namespace pn ON pn.oid=pc.relnamespace WHERE i.inhrelid=c.oid ORDER BY i.inhseqno),
 'view',CASE WHEN c.relkind IN ('v','m') THEN pg_get_viewdef(c.oid) END,
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',at.attname,'type',format_type(at.atttypid,at.atttypmod),'notnull',at.attnotnull,'identity',at.attidentity,'generated',at.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(ax.grantor),'grantee',CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,'privilege',ax.privilege_type,'grantable',ax.is_grantable) ORDER BY pg_get_userbyid(ax.grantor),CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,ax.privilege_type,ax.is_grantable) FROM aclexplode(CASE WHEN cardinality(at.attacl)>0 THEN at.attacl END) ax),'[]'::jsonb),'collation',CASE WHEN at.attcollation<>0 THEN at.attcollation::regcollation::text END,'storage',at.attstorage,'compression',at.attcompression,'statistics',at.attstattarget,'options',ARRAY(SELECT x FROM unnest(at.attoptions) x ORDER BY x)) ORDER BY at.attnum)
 FROM pg_attribute at LEFT JOIN pg_attrdef d ON d.adrelid=at.attrelid AND d.adnum=at.attnum WHERE at.attrelid=c.oid AND at.attnum>0 AND NOT at.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated,'deferrable',condeferrable,'deferred',condeferred,'no_inherit',connoinherit) ORDER BY conname) FROM pg_constraint WHERE conrelid=c.oid),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'clustered',i.indisclustered,'replica_identity',i.indisreplident,'options',ARRAY(SELECT x FROM unnest(ic.reloptions) x ORDER BY x),'tablespace',CASE WHEN ic.reltablespace=0 THEN NULL ELSE (SELECT spcname FROM pg_tablespace WHERE oid=ic.reltablespace) END) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'policies',(SELECT jsonb_agg(jsonb_build_object('name',polname,'command',polcmd,'permissive',polpermissive,'roles',ARRAY(SELECT CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_oid) END FROM unnest(polroles) role_oid ORDER BY CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_oid) END),'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid)) ORDER BY polname) FROM pg_policy WHERE polrelid=c.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(oid),'enabled',tgenabled) ORDER BY tgname) FROM pg_trigger WHERE tgrelid=c.oid AND NOT tgisinternal),
 'rules',(SELECT jsonb_agg(jsonb_build_object('name',rulename,'definition',pg_get_ruledef(oid),'enabled',ev_enabled) ORDER BY rulename) FROM pg_rewrite WHERE ev_class=c.oid AND rulename<>'_RETURN')) ORDER BY c.nspname,c.relname) FROM relations c),
 'sequences',(SELECT jsonb_agg(jsonb_build_object('schema',c.nspname,'name',c.relname,'type',format_type(s.seqtypid,NULL),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle,
 'owned_by',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'relation',t.relname,'column',a.attname,'dependency',d.deptype) ORDER BY n.nspname,t.relname,a.attname,d.deptype) FROM pg_depend d JOIN pg_class t ON t.oid=d.refobjid JOIN pg_namespace n ON n.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=d.refobjsubid WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.refclassid='pg_class'::regclass AND d.deptype IN ('a','i'))) ORDER BY c.nspname,c.relname) FROM pg_sequence s JOIN relations c ON c.oid=s.seqrelid),
 'routines',(SELECT jsonb_agg(jsonb_build_object('schema',p.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'kind',p.prokind,'owner',pg_get_userbyid(p.proowner),'acl',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(ax.grantor),'grantee',CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,'privilege',ax.privilege_type,'grantable',ax.is_grantable) ORDER BY pg_get_userbyid(ax.grantor),CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,ax.privilege_type,ax.is_grantable) FROM aclexplode(CASE WHEN cardinality(coalesce(p.proacl,acldefault('f',p.proowner)))>0 THEN coalesce(p.proacl,acldefault('f',p.proowner)) END) ax),'[]'::jsonb),'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'definer',p.prosecdef,'settings',p.proconfig,'volatility',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'leakproof',p.proleakproof,'cost',p.procost,'rows',p.prorows,'support',CASE WHEN p.prosupport=0 THEN NULL ELSE p.prosupport::regprocedure::text END,'definition_md5',CASE WHEN p.prokind<>'a' THEN md5(pg_get_functiondef(p.oid)) END,
 'aggregate',(SELECT jsonb_build_object('kind',ag.aggkind,'direct_args',ag.aggnumdirectargs,'transition',ag.aggtransfn::regprocedure::text,'final',ag.aggfinalfn::regprocedure::text,'combine',ag.aggcombinefn::regprocedure::text,'serialize',ag.aggserialfn::regprocedure::text,'deserialize',ag.aggdeserialfn::regprocedure::text,'moving_transition',ag.aggmtransfn::regprocedure::text,'moving_inverse',ag.aggminvtransfn::regprocedure::text,'moving_final',ag.aggmfinalfn::regprocedure::text,'final_extra',ag.aggfinalextra,'moving_final_extra',ag.aggmfinalextra,'final_modify',ag.aggfinalmodify,'moving_final_modify',ag.aggmfinalmodify,'sort_operator',ag.aggsortop::regoperator::text,'transition_type',format_type(ag.aggtranstype,NULL),'transition_space',ag.aggtransspace,'moving_type',CASE WHEN ag.aggmtranstype=0 THEN NULL ELSE format_type(ag.aggmtranstype,NULL) END,'moving_space',ag.aggmtransspace,'initial',ag.agginitval,'moving_initial',ag.aggminitval) FROM pg_aggregate ag WHERE ag.aggfnoid=p.oid)) ORDER BY p.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM routines p),
 'types',(SELECT jsonb_agg(jsonb_build_object('schema',t.nspname,'name',t.typname,'kind',t.typtype,'owner',pg_get_userbyid(t.typowner),'acl',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(ax.grantor),'grantee',CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,'privilege',ax.privilege_type,'grantable',ax.is_grantable) ORDER BY pg_get_userbyid(ax.grantor),CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,ax.privilege_type,ax.is_grantable) FROM aclexplode(CASE WHEN cardinality(coalesce(t.typacl,acldefault('T',t.typowner)))>0 THEN coalesce(t.typacl,acldefault('T',t.typowner)) END) ax),'[]'::jsonb),'enum',(SELECT jsonb_agg(enumlabel ORDER BY enumsortorder) FROM pg_enum WHERE enumtypid=t.oid),'domain_type',CASE WHEN t.typbasetype<>0 THEN format_type(t.typbasetype,t.typtypmod) END,'domain_notnull',t.typnotnull,'domain_default',t.typdefault,'domain_constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated) ORDER BY conname) FROM pg_constraint WHERE contypid=t.oid),
 'composite',(SELECT jsonb_agg(jsonb_build_object('name',at.attname,'type',format_type(at.atttypid,at.atttypmod),'collation',CASE WHEN at.attcollation=0 THEN NULL ELSE at.attcollation::regcollation::text END) ORDER BY at.attnum) FROM pg_attribute at WHERE at.attrelid=t.typrelid AND at.attnum>0 AND NOT at.attisdropped),
 'range',(SELECT jsonb_build_object('subtype',format_type(r.rngsubtype,NULL),'collation',CASE WHEN r.rngcollation=0 THEN NULL ELSE r.rngcollation::regcollation::text END,'operator_class',(SELECT format('%I.%I',n.nspname,op.opcname) FROM pg_opclass op JOIN pg_namespace n ON n.oid=op.opcnamespace WHERE op.oid=r.rngsubopc),'canonical',r.rngcanonical::regprocedure::text,'subdiff',r.rngsubdiff::regprocedure::text,'multirange',format_type(r.rngmultitypid,NULL)) FROM pg_range r WHERE r.rngtypid=t.oid OR r.rngmultitypid=t.oid),
 'base',CASE WHEN t.typtype='b' THEN jsonb_build_object('length',t.typlen,'by_value',t.typbyval,'category',t.typcategory,'preferred',t.typispreferred,'delimiter',t.typdelim,'input',t.typinput::regprocedure::text,'output',t.typoutput::regprocedure::text,'receive',t.typreceive::regprocedure::text,'send',t.typsend::regprocedure::text,'typmod_in',t.typmodin::regprocedure::text,'typmod_out',t.typmodout::regprocedure::text,'analyze',t.typanalyze::regprocedure::text,'subscript',t.typsubscript::regprocedure::text,'alignment',t.typalign,'storage',t.typstorage,'default',t.typdefault,'collation',CASE WHEN t.typcollation=0 THEN NULL ELSE t.typcollation::regcollation::text END) END) ORDER BY t.nspname,t.typname) FROM types t),
 'event_triggers',(SELECT jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'owner',pg_get_userbyid(evtowner),'function',evtfoid::regprocedure::text,'enabled',evtenabled,'tags',ARRAY(SELECT x FROM unnest(evttags) x ORDER BY x)) ORDER BY evtname) FROM pg_event_trigger),
 'defaults',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',CASE WHEN d.defaclnamespace<>0 THEN d.defaclnamespace::regnamespace::text END,'type',d.defaclobjtype,'acl',coalesce((SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(ax.grantor),'grantee',CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,'privilege',ax.privilege_type,'grantable',ax.is_grantable) ORDER BY pg_get_userbyid(ax.grantor),CASE WHEN ax.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ax.grantee) END,ax.privilege_type,ax.is_grantable) FROM aclexplode(CASE WHEN cardinality(d.defaclacl)>0 THEN d.defaclacl END) ax),'[]'::jsonb)) ORDER BY pg_get_userbyid(d.defaclrole),d.defaclnamespace::regnamespace::text,d.defaclobjtype) FROM pg_default_acl d),
 'publications',(SELECT jsonb_agg(jsonb_build_object('name',p.pubname,'owner',pg_get_userbyid(p.pubowner),'all_tables',p.puballtables,'insert',p.pubinsert,'update',p.pubupdate,'delete',p.pubdelete,'truncate',p.pubtruncate,'via_root',p.pubviaroot,
 'schemas',ARRAY(SELECT n.nspname FROM pg_publication_namespace pn JOIN pg_namespace n ON n.oid=pn.pnnspid WHERE pn.pnpubid=p.oid ORDER BY n.nspname),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'columns',CASE WHEN pr.prattrs IS NULL THEN NULL ELSE ARRAY(SELECT a.attname FROM unnest(pr.prattrs) num JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum=num ORDER BY a.attname) END,'filter',pg_get_expr(pr.prqual,pr.prrelid)) ORDER BY n.nspname,c.relname) FROM pg_publication_rel pr JOIN pg_class c ON c.oid=pr.prrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE pr.prpubid=p.oid)) ORDER BY p.pubname) FROM pg_publication p),
 'comments',(SELECT jsonb_agg(jsonb_build_object('object',pg_describe_object(d.classoid,d.objoid,d.objsubid),'comment',d.description) ORDER BY pg_describe_object(d.classoid,d.objoid,d.objsubid)) FROM pg_description d WHERE (d.classoid='pg_namespace'::regclass AND d.objoid IN(SELECT oid FROM namespaces)) OR (d.classoid='pg_class'::regclass AND d.objoid IN(SELECT oid FROM relations UNION SELECT indexrelid FROM pg_index WHERE indrelid IN(SELECT oid FROM relations))) OR (d.classoid='pg_proc'::regclass AND d.objoid IN(SELECT oid FROM routines)) OR (d.classoid='pg_type'::regclass AND d.objoid IN(SELECT oid FROM types)) OR (d.classoid='pg_constraint'::regclass AND d.objoid IN(SELECT oid FROM pg_constraint WHERE conrelid IN(SELECT oid FROM relations) OR contypid IN(SELECT oid FROM types))) OR (d.classoid='pg_trigger'::regclass AND d.objoid IN(SELECT oid FROM pg_trigger WHERE tgrelid IN(SELECT oid FROM relations))) OR (d.classoid='pg_rewrite'::regclass AND d.objoid IN(SELECT oid FROM pg_rewrite WHERE ev_class IN(SELECT oid FROM relations))) OR d.classoid IN('pg_event_trigger'::regclass,'pg_publication'::regclass,'pg_extension'::regclass)),
 'security_labels',(SELECT jsonb_agg(jsonb_build_object('object',pg_describe_object(s.classoid,s.objoid,s.objsubid),'provider',s.provider,'label_md5',md5(s.label)) ORDER BY pg_describe_object(s.classoid,s.objoid,s.objsubid),s.provider) FROM pg_seclabel s WHERE (s.classoid='pg_namespace'::regclass AND s.objoid IN(SELECT oid FROM namespaces)) OR (s.classoid='pg_class'::regclass AND s.objoid IN(SELECT oid FROM relations)) OR (s.classoid='pg_proc'::regclass AND s.objoid IN(SELECT oid FROM routines)) OR (s.classoid='pg_type'::regclass AND s.objoid IN(SELECT oid FROM types))),
 'unsupported_objects',(SELECT jsonb_agg(jsonb_build_object('class',class,'count',n) ORDER BY class) FROM (
 SELECT 'nonextension_user_casts' AS class,count(*) AS n FROM pg_cast c JOIN pg_type a ON a.oid=c.castsource JOIN pg_type b ON b.oid=c.casttarget WHERE (a.typnamespace IN (SELECT oid FROM namespaces) OR b.typnamespace IN (SELECT oid FROM namespaces)) AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_cast'::regclass AND d.objid=c.oid AND d.deptype IN ('e','i')) UNION ALL
 SELECT 'nonextension_languages',count(*) FROM pg_language l WHERE l.lanname NOT IN ('c','internal','sql') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_language'::regclass AND d.objid=l.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_access_methods',count(*) FROM pg_am a WHERE a.oid>=16384 AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_am'::regclass AND d.objid=a.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_extended_statistics',count(*) FROM pg_statistic_ext s WHERE s.stxnamespace IN (SELECT oid FROM namespaces) AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_statistic_ext'::regclass AND d.objid=s.oid AND d.deptype='e') UNION ALL
 SELECT 'foreign_servers',count(*) FROM pg_foreign_server UNION ALL SELECT 'foreign_user_mappings',count(*) FROM pg_user_mapping UNION ALL SELECT 'subscriptions',count(*) FROM pg_subscription UNION ALL
 SELECT 'nonextension_operators',count(*) FROM pg_operator o JOIN namespaces n ON n.oid=o.oprnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_operator'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_operator_classes',count(*) FROM pg_opclass o JOIN namespaces n ON n.oid=o.opcnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_opclass'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_operator_families',count(*) FROM pg_opfamily o JOIN namespaces n ON n.oid=o.opfnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_opfamily'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_collations',count(*) FROM pg_collation o JOIN namespaces n ON n.oid=o.collnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_collation'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_conversions',count(*) FROM pg_conversion o JOIN namespaces n ON n.oid=o.connamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_conversion'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_text_search_configurations',count(*) FROM pg_ts_config o JOIN namespaces n ON n.oid=o.cfgnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_ts_config'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_text_search_dictionaries',count(*) FROM pg_ts_dict o JOIN namespaces n ON n.oid=o.dictnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_ts_dict'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_text_search_parsers',count(*) FROM pg_ts_parser o JOIN namespaces n ON n.oid=o.prsnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_ts_parser'::regclass AND d.objid=o.oid AND d.deptype='e') UNION ALL
 SELECT 'nonextension_text_search_templates',count(*) FROM pg_ts_template o JOIN namespaces n ON n.oid=o.tmplnamespace WHERE NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_ts_template'::regclass AND d.objid=o.oid AND d.deptype='e')
 ) x)
);
COMMIT;
